464	pub fn run_seconds(args: &SecondsArgs) -> anyhow::Result<SecondsSummary> {
465	    super::require_verified(&args.root, &args.symbol, args.allow_unverified)?;
466	    let paths = super::session_binlog_for(&args.root, &args.symbol)?;
467	    anyhow::ensure!(
468	        !paths.is_empty(),
469	        "{}: нет суточных файлов {}",
470	        args.root.display(),
471	        args.symbol
472	    );
473	    let prefix = format!("{}-", args.symbol);
474	    let mut by_day: Vec<(String, Vec<PathBuf>)> = Vec::new();
475	    for path in paths {
476	        let name = path
477	            .file_name()
478	            .map(|s| s.to_string_lossy().into_owned())
479	            .unwrap_or_default();
480	        let day = day_of_filename(&prefix, &name)
481	            .ok_or_else(|| anyhow::anyhow!("имя {name} не разбирается как сутки"))?;
482	        if !args.days.is_empty() && !args.days.iter().any(|d| d == &day) {
483	            continue;
484	        }
485	        match by_day.last_mut() {
486	            Some((d, v)) if *d == day => v.push(path),
487	            _ => by_day.push((day, vec![path])),
488	        }
489	    }
490	    anyhow::ensure!(!by_day.is_empty(), "нет суток под --day");
491	    let out_dir = args.out.clone().unwrap_or_else(|| {
492	        args.root
493	            .join(if args.bbo_events { "bbo" } else { "seconds" })
494	    });
495	    std::fs::create_dir_all(&out_dir)?;
496	    let (mut trades, mut dropped, mut gap_secs, mut bbo_rows) = (0u64, 0u64, 0u64, 0u64);
497	    for (day, parts) in &by_day {
498	        if args.bbo_events {
499	            let path = out_dir.join(format!("{}-{day}.csv", args.symbol));
500	            let file = std::io::BufWriter::new(std::fs::File::create(&path)?);
501	            let mut acc = BboAcc::new(day_start_ms(day)?, file)?;
502	            for p in parts {
503	                feed_file(p, &mut acc)?;
504	            }
505	            bbo_rows += acc.finish()?;
506	            continue;
507	        }
508	        let mut acc = DayAcc::new(day_start_ms(day)?);
509	        for p in parts {
510	            feed_file(p, &mut acc)?;
511	        }
512	        trades += acc.trades;
513	        dropped += acc.dropped;
514	        let rows = acc.finish();
515	        gap_secs += rows.iter().filter(|r| r[12] == 1).count() as u64;
516	        let path = out_dir.join(format!("{}-{day}.csv", args.symbol));
517	        let mut w = csv::Writer::from_path(&path)?;
518	        w.write_record(SECONDS_COLUMNS)?;
519	        for r in &rows {
520	            w.write_record(r.map(|v| v.to_string()))?;
521	        }
522	        w.flush()?;
523	    }
524	    Ok(SecondsSummary {
525	        days: by_day.len(),
526	        trades,
527	        dropped,
528	        gap_secs,
529	        bbo_rows,
530	        out_dir,
531	    })
532	}
