fn feed_file<F: Feed>(path: &Path, acc: &mut F) -> anyhow::Result<ApplyGuard> {
    let data = std::fs::read(path)
        .map_err(|e| anyhow::anyhow!("файл {} не читается: {e}", path.display()))?;
